function formatDateLabel(isoDate) {
  const d = new Date(isoDate + 'T00:00:00');
  const month = MONTH_NAMES[d.getMonth()];
  const day = d.getDate();
  const weekday = WEEKDAYS[d.getDay()];
  return `${month} ${day}일 ${weekday}요일`;
}

