  const { tasks, selectedDate, error } = state;

  // Update header date
  const dateEl = document.getElementById('selected-date');
  if (dateEl) dateEl.textContent = formatDateLabel(selectedDate);

  // Rebuild week strip
  const weekStrip = document.getElementById('week-days');
  if (weekStrip) {
    const dates = weekDates(selectedDate);
    weekStrip.replaceChildren();
    for (const date of dates) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'day-button';
      btn.dataset.date = date;
      const d = new Date(date + 'T00:00:00');
      const month = MONTH_NAMES[d.getMonth()];
      const day = d.getDate();
      const weekday = WEEKDAYS[d.getDay()];
      btn.setAttribute('aria-label', `${month} ${day}일 ${weekday}요일`);
      btn.setAttribute('aria-pressed', date === selectedDate ? 'true' : 'false');

      const spanWeek = document.createElement('span');
      spanWeek.className = 'weekday';
      spanWeek.textContent = weekday;

      const spanDay = document.createElement('span');
