  const studyTasks = dayTasks.filter(t => t.category === 'study');
  const lifeTasks = dayTasks.filter(t => t.category === 'life');

  const emptyState = document.getElementById('empty-state');
  if (emptyState) {
    emptyState.style.display = dayTasks.length > 0 ? 'none' : '';
  }

  // Render study tasks
  const studyList = document.getElementById('study-items');
  if (studyList) {
    const template = document.getElementById('task-template');
    studyList.replaceChildren();
    for (const task of studyTasks) {
      const clone = template.content.cloneNode(true);
      const li = clone.querySelector('li');
      if (!li) continue;
      li.dataset.id = task.id;
      if (task.completed) li.classList.add('is-complete');

      const checkbox = li.querySelector('.task-check');
      if (checkbox) checkbox.checked = task.completed;

      const nameSpan = li.querySelector('.task-name');
      if (nameSpan) nameSpan.textContent = task.title;

      const delBtn = li.querySelector('.delete-task');
      if (delBtn) delBtn.setAttribute('aria-label', `할 일 삭제: ${task.title}`);

      studyList.append(clone);
    }
  }

  // Render life tasks
